// This endpoint is polled several times a minute, so the run row has to
// answer everything without waking the agent or making a paid call.
const rows = $input.all().map((item) => item.json).filter((row) => row && row.runId);
const latest = rows[0] ?? null;
if (!latest) {
  return [{ json: { schemaVersion: 1, hasRun: false, running: false } }];
}

const minutesSince = (value) => {
  const parsed = Date.parse(String(value ?? ''));
  if (Number.isNaN(parsed)) return null;
  return Math.max(0, Math.round((Date.now() - parsed) / 60000));
};
const status = String(latest.status ?? '');
const running = ['queued', 'running'].includes(status);

// While the run is open, errorSummary is safe scratch space for its heartbeat.
// The final save replaces it with the real error summary. This works for tables
// created before progress existed, because setup cannot add columns in place.
let heartbeat = null;
if (running) {
  try {
    const parsed = JSON.parse(String(latest.errorSummary ?? ''));
    if (parsed && parsed.hb === 1) heartbeat = parsed;
  } catch {}
}
const startedMinutesAgo = minutesSince(latest.startedAt);
const quietMinutes = heartbeat ? minutesSince(heartbeat.at) : startedMinutesAgo;
const QUIET_AFTER = 30;
const DEAD_AFTER = 120;
const interrupted = running && (heartbeat
  ? quietMinutes !== null && quietMinutes >= QUIET_AFTER
  : startedMinutesAgo !== null && startedMinutesAgo >= DEAD_AFTER);

if (running && !interrupted) {
  return [{ json: {
    schemaVersion: 1,
    hasRun: true,
    running: true,
    runId: String(latest.runId),
    monthLabel: String(latest.monthLabel ?? ''),
    startedAt: String(latest.startedAt ?? ''),
    startedMinutesAgo,
    step: heartbeat ? Number(heartbeat.step) || 0 : 0,
    of: heartbeat ? Number(heartbeat.of) || 7 : 7,
    note: heartbeat ? String(heartbeat.note ?? '').slice(0, 200) : 'Getting the monthly update started',
    updatedMinutesAgo: quietMinutes,
  } }];
}

return [{ json: {
  schemaVersion: 1,
  hasRun: true,
  running: false,
  interrupted,
  runId: String(latest.runId),
  monthLabel: String(latest.monthLabel ?? ''),
  status: interrupted ? 'interrupted' : status,
  finishedAt: interrupted ? '' : String(latest.finishedAt ?? ''),
} }];
